package gg.hazard.spotify.extra.tablist;

import lombok.Getter;
import lombok.Setter;
import lombok.experimental.UtilityClass;
import gg.hazard.spotify.extra.skin.CachedSkin;

import java.util.HashMap;
import java.util.Map;

@Getter @Setter
@UtilityClass
public class Heads {

    private final Map<String, CachedSkin> HEADS = new HashMap<>();

    static {

        addHead(
                "dark_gray",
                "",
                ""
        );

        addHead(
                "clock_head",
                "",
                ""
        );

        addHead(
                "twitter_head",
                "",
                ""
        );

        addHead(
                "store_head",
                "",
                ""
        );

        addHead(
                "console_head",
                "",
                ""
        );

        addHead(
                "ping_head",
                "",
                ""
        );

        addHead(
                "discord_head",
                "",
                ""
        );

        addHead(
                "website_head",
                "",
                ""
        );

        addHead(
                "info_head",
                "",
                ""
        );
    }

    private void addHead(String key, String texture, String signature) {
        HEADS.put(key, new CachedSkin(key, texture, signature));
    }

    public CachedSkin getHead(String key) {
        return HEADS.getOrDefault(key.toLowerCase(), HEADS.get("dark_gray"));
    }
}
